#include "content/ProductionRecipeCatalogue.hpp"
namespace elysium::content {void ProductionRecipeCatalogue::addRawSource(ContentId id){if(id)raw_.insert(id);}void ProductionRecipeCatalogue::addKnownStation(ContentId id){if(id)stations_.insert(id);}bool ProductionRecipeCatalogue::add(ProductionRecipe r){if(!r.id||!r.output||!r.outputAmount||recipes_.contains(r.id))return false;for(auto&i:r.inputs)if(!i.id||!i.amount)return false;recipes_[r.id]=std::move(r);return true;}const ProductionRecipe*ProductionRecipeCatalogue::find(ContentId id)const{auto i=recipes_.find(id);return i==recipes_.end()?nullptr:&i->second;}bool ProductionRecipeCatalogue::obtainableImpl(ContentId item,std::set<ContentId>&stack)const{if(raw_.contains(item))return true;if(!stack.insert(item).second)return false;bool ok=false;for(auto&[id,r]:recipes_)if(r.output==item&&r.status!=RecipeStatus::Proposed){if(!r.station||stations_.contains(r.station)){ok=true;for(auto&i:r.inputs)ok&=obtainableImpl(i.id,stack);if(ok)break;}}stack.erase(item);return ok;}bool ProductionRecipeCatalogue::obtainable(ContentId item)const{std::set<ContentId>s;return obtainableImpl(item,s);}std::vector<RecipeIssue>ProductionRecipeCatalogue::validate()const{std::vector<RecipeIssue>o;for(auto&[id,r]:recipes_){if(r.station&&!stations_.contains(r.station))o.push_back({id,"missing_station"});if(r.status!=RecipeStatus::Proposed&&!obtainable(r.output))o.push_back({id,"unobtainable_required_output"});std::uint64_t in=0;for(auto&i:r.inputs){if(in>UINT64_MAX-i.amount){in=UINT64_MAX;break;}in+=i.amount;}if(in==0)o.push_back({id,"free_output_recipe"});}return o;}}
